window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-ba43b4b353badfc6"]={"versions": [{"id": "FIG-ba43b4b353badfc6", "releases": ["R18-10_R4.4.0_R1.5.0", "R19-11", "R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">SPEM-2.0-Aktivitäts- und Prozessdiagramm im Kontext der AUTOSAR-Methodik für das Timing-Modellierungs-Verfahren auf Steuergeräteebene (ECU Use-Case „Create Timing Model of the entire ECU“ gemäß AUTOSAR_TR_TimingAnalysis).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Aktivitäten / Schritte:</strong>\n<ul class=\"fig-list\"><li><code>«ecu» Collect Timing Information of a SW-C</code> (vorgelagerte Aktivität / Use-Case-Schritt, referenziert aus einem externen Kontext <code>(from ...)</code>).\n</li><li><code>Create Timing Model</code> (SPEM-Task-Definition / Hauptaktivität).\n</li></ul>\n</li><li><strong>Artefakte / Work Products:</strong>\n<ul class=\"fig-list\"><li><code>Timing Model SWC</code>: Dokument-/Modell-Artefakt, dient als Eingangsartefakt (<code>«input»</code>) für <code>Create Timing Model</code>.\n</li><li><code>Timing Model E...</code> (<code>Timing Model ECU</code>): Dokument-/Modell-Artefakt, dient als Ausgangsartefakt (<code>«output»</code>) der Aktivität <code>Create Timing Model</code>.\n</li></ul>\n</li><li><strong>Beziehungen / Schnittstellen:</strong>\n<ul class=\"fig-list\"><li>Gestrichelte Abhängigkeitspfeillinie von <code>«ecu» Collect Timing Information of a SW-C</code> zum Artefakt <code>Timing Model SWC</code>.\n</li><li>Gerichtete Flusskante (<code>«input»</code>) von <code>Timing Model SWC</code> zu <code>Create Timing Model</code>.\n</li><li>Gerichtete Flusskante (<code>«output»</code>) von <code>Create Timing Model</code> zum Ergebnisartefakt <code>Timing Model ECU</code>.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Timing-Informationen einzelner Software-Komponenten werden im Rahmen der Aktivität <code>Collect Timing Information of a SW-C</code> erhoben und im Artefakt <code>Timing Model SWC</code> bereitgestellt.\n</li><li>Das Artefakt <code>Timing Model SWC</code> wird als <code>«input»</code> in den Prozessschritt <code>Create Timing Model</code> eingespeist.\n</li><li>Die Aktivität <code>Create Timing Model</code> aggregiert bzw. verarbeitet diese Eingangsdaten und erzeugt als <code>«output»</code> das Gesamt-Timing-Modell des Steuergeräts (<code>Timing Model ECU</code>).\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm beschreibt den methodischen Ablauf zur Aggregation von Komponenten-Timing-Beschreibungen zu einem steuergeräteübergreifenden Timing-Modell. Für die Werkzeugkette bedeutet dies, dass Werkzeuge zur Erstellung des ECU-Timing-Modells das XML-/ARXML-Artefakt des SWC-Timing-Modells einlesen können müssen, um das konsolidierte ECU-Timing-Modell zu generieren.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-7f5bee9fe889040d", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">SPEM-2.0-Aktivitäts- und Prozessdiagramm im Kontext der AUTOSAR-Methodik für das Timing-Modellierungs-Verfahren auf Steuergeräteebene (ECU Use-Case „Create Timing Model of the entire ECU“ gemäß AUTOSAR_TR_TimingAnalysis).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Aktivitäten / Schritte:</strong>\n<ul class=\"fig-list\"><li><code>«ecu» Collect Timing Information of a SW-C</code> (vorgelagerte Aktivität / Use-Case-Schritt, referenziert aus einem externen Kontext <code>(from ...)</code>).\n</li><li><code>Create Timing Model</code> (SPEM-Task-Definition / Hauptaktivität).\n</li></ul>\n</li><li><strong>Artefakte / Work Products:</strong>\n<ul class=\"fig-list\"><li><code>Timing Model SWC</code>: Dokument-/Modell-Artefakt, dient als Eingangsartefakt (<code>«input»</code>) für <code>Create Timing Model</code>.\n</li><li><code>Timing Model E...</code> (<code>Timing Model ECU</code>): Dokument-/Modell-Artefakt, dient als Ausgangsartefakt (<code>«output»</code>) der Aktivität <code>Create Timing Model</code>.\n</li></ul>\n</li><li><strong>Beziehungen / Schnittstellen:</strong>\n<ul class=\"fig-list\"><li>Gestrichelte Abhängigkeitspfeillinie von <code>«ecu» Collect Timing Information of a SW-C</code> zum Artefakt <code>Timing Model SWC</code>.\n</li><li>Gerichtete Flusskante (<code>«input»</code>) von <code>Timing Model SWC</code> zu <code>Create Timing Model</code>.\n</li><li>Gerichtete Flusskante (<code>«output»</code>) von <code>Create Timing Model</code> zum Ergebnisartefakt <code>Timing Model ECU</code>.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Timing-Informationen einzelner Software-Komponenten werden im Rahmen der Aktivität <code>Collect Timing Information of a SW-C</code> erhoben und im Artefakt <code>Timing Model SWC</code> bereitgestellt.\n</li><li>Das Artefakt <code>Timing Model SWC</code> wird als <code>«input»</code> in den Prozessschritt <code>Create Timing Model</code> eingespeist.\n</li><li>Die Aktivität <code>Create Timing Model</code> aggregiert bzw. verarbeitet diese Eingangsdaten und erzeugt als <code>«output»</code> das Gesamt-Timing-Modell des Steuergeräts (<code>Timing Model ECU</code>).\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm beschreibt den methodischen Ablauf zur Aggregation von Komponenten-Timing-Beschreibungen zu einem steuergeräteübergreifenden Timing-Modell. Für die Werkzeugkette bedeutet dies, dass Werkzeuge zur Erstellung des ECU-Timing-Modells das XML-/ARXML-Artefakt des SWC-Timing-Modells einlesen können müssen, um das konsolidierte ECU-Timing-Modell zu generieren.</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-ba43b4b353badfc6", "to": "FIG-7f5bee9fe889040d", "fr": "R20-11", "tr": "R21-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
